1	import { SCORE_THRESHOLDS } from "./constants";
2	import type { Severity, Effort, CroPillar, PageType, PillarResult } from "@/types";
3	
4	// ── Score Colors ─────────────────────────────────────────────
5	
6	export function getScoreColor(score: number): string {
7	  if (score < SCORE_THRESHOLDS.poor) return "text-red-500";
8	  if (score < SCORE_THRESHOLDS.average) return "text-amber-500";
9	  return "text-green-500";
10	}
11	
12	export function getScoreBgColor(score: number): string {
13	  if (score < SCORE_THRESHOLDS.poor) return "bg-red-500";
14	  if (score < SCORE_THRESHOLDS.average) return "bg-amber-500";
15	  return "bg-green-500";
16	}
17	
18	export function getScoreBgLight(score: number): string {
19	  if (score < SCORE_THRESHOLDS.poor) return "bg-red-50";
20	  if (score < SCORE_THRESHOLDS.average) return "bg-amber-50";
21	  return "bg-green-50";
22	}
23	
24	export function getScoreHex(score: number): string {
25	  if (score < SCORE_THRESHOLDS.poor) return "#EF4444";
26	  if (score < SCORE_THRESHOLDS.average) return "#F59E0B";
27	  return "#22C55E";
28	}
29	
30	export function getScoreLabel(score: number): string {
31	  if (score < 20) return "Critical";
32	  if (score < SCORE_THRESHOLDS.poor) return "Poor";
33	  if (score < 55) return "Below Average";
34	  if (score < SCORE_THRESHOLDS.average) return "Average";
35	  if (score < 85) return "Good";
36	  return "Excellent";
37	}
38	
39	// ── Severity ─────────────────────────────────────────────────
40	
41	export function getSeverityColor(severity: Severity): {
42	  bg: string;
43	  text: string;
44	  border: string;
45	  dot: string;
46	} {
47	  switch (severity) {
48	    case "critical":
49	      return { bg: "bg-red-50", text: "text-red-700", border: "border-red-200", dot: "bg-red-500" };
50	    case "warning":
51	      return { bg: "bg-amber-50", text: "text-amber-700", border: "border-amber-200", dot: "bg-amber-500" };
52	    case "info":
53	      return { bg: "bg-blue-50", text: "text-blue-700", border: "border-blue-200", dot: "bg-blue-500" };
54	    case "passed":
55	      return { bg: "bg-green-50", text: "text-green-700", border: "border-green-200", dot: "bg-green-500" };
56	  }
57	}
58	
59	export function getSeverityLabel(severity: Severity): string {
60	  switch (severity) {
61	    case "critical": return "Critical";
62	    case "warning": return "Warning";
63	    case "info": return "Info";
64	    case "passed": return "Passed";
65	  }
66	}
67	
68	// ── Effort ───────────────────────────────────────────────────
69	
70	export function getEffortLabel(effort: Effort): string {
71	  switch (effort) {
72	    case "quick": return "Quick Win";
73	    case "moderate": return "Moderate";
74	    case "significant": return "Significant";
75	  }
76	}
77	
78	export function getEffortColor(effort: Effort): string {
79	  switch (effort) {
80	    case "quick": return "text-green-600 bg-green-50 border-green-200";
81	    case "moderate": return "text-amber-600 bg-amber-50 border-amber-200";
82	    case "significant": return "text-slate-600 bg-slate-50 border-slate-200";
83	  }
84	}
