1	import { useEffect, useState } from "react";
2	import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
3	import { cn } from "@/lib/utils";
4	
5	interface ScoreRingProps {
6	  score: number;
7	  size?: number;
8	  strokeWidth?: number;
9	  showLabel?: boolean;
10	  className?: string;
11	}
12	
13	export function ScoreRing({
14	  score,
15	  size = 120,
16	  strokeWidth = 8,
17	  showLabel = true,
18	  className,
19	}: ScoreRingProps) {
20	  const [animatedOffset, setAnimatedOffset] = useState(0);
21	  const radius = (size - strokeWidth) / 2;
22	  const circumference = 2 * Math.PI * radius;
23	  const targetOffset = circumference * (1 - score / 100);
24	
25	  useEffect(() => {
26	    setAnimatedOffset(circumference);
27	    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50);
28	    return () => clearTimeout(timer);
29	  }, [score, circumference, targetOffset]);
30	
31	  const color = getScoreHex(score);
32	  const label = getScoreLabel(score);
33	  const center = size / 2;
34	  const fontSize = size * 0.28;
35	  const labelSize = size * 0.09;
36	
37	  // Glow shadow based on score color
38	  const glowShadow = score >= 70
39	    ? "drop-shadow(0 0 6px rgba(34, 197, 94, 0.2))"
40	    : score >= 40
41	    ? "drop-shadow(0 0 6px rgba(245, 158, 11, 0.2))"
42	    : "drop-shadow(0 0 6px rgba(239, 68, 68, 0.2))";
43	
44	  return (
45	    <div
46	      role="img"
47	      aria-label={`CRO Score: ${score} out of 100`}
48	      className={cn("relative inline-flex flex-col items-center", className)}
49	    >
50	      <svg
51	        width={size}
52	        height={size}
53	        className="transform -rotate-90"
54	        style={{ filter: glowShadow }}
55	      >
56	        {/* Background circle */}
57	        <circle
58	          cx={center}
59	          cy={center}
60	          r={radius}
61	          fill="none"
62	          stroke="currentColor"
63	          strokeWidth={strokeWidth}
64	          className="text-muted/60"
65	        />
66	        {/* Score circle */}
67	        <circle
68	          cx={center}
69	          cy={center}
70	          r={radius}
71	          fill="none"
72	          stroke={color}
73	          strokeWidth={strokeWidth}
74	          strokeLinecap="round"
75	          strokeDasharray={circumference}
76	          strokeDashoffset={animatedOffset}
77	          style={{ transition: "stroke-dashoffset 1s ease-out" }}
78	        />
79	      </svg>
80	      {/* Score number centered */}
81	      <div className="absolute inset-0 flex flex-col items-center justify-center">
82	        <span
83	          className="font-semibold text-foreground tabular-nums"
84	          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
85	        >
86	          {score}
87	        </span>
88	        <span
89	          className="text-muted-foreground"
90	          style={{ fontSize: `${labelSize}px` }}
91	        >
92	          /100
93	        </span>
94	      </div>
95	      {showLabel && (
96	        <span
97	          className="mt-1 text-xs font-medium"
98	          style={{ color }}
99	        >
100	          {label}
101	        </span>
102	      )}
103	    </div>
104	  );
105	}
